--
-- Las fechas de las clases son relativas al día del reset: la sesión "actual"
-- de cada curso cae el sábado de la semana en curso.
-- =============================================================================

BEGIN;

-- Sábado de la semana en curso (base de las fechas de clases)
CREATE TEMP TABLE _base ON COMMIT DROP AS SELECT (current_date + (6 - extract(isodow FROM current_date)::int))::date AS sabado;

-- Sedes

-- Catálogo de cursos

-- Catálogo de roles de tutoras (los 4 del enum anterior quedan inactivos)
UPDATE public.rol_tarea_tutor SET activo = false WHERE codigo IN ('tutora_lider', 'tutora_apoyo', 'registro_asistencia', 'dinamica_kahoot');

-- Correos autorizados del staff (registro cerrado, US-04)

-- Cuentas del staff

-- Voluntariado: ficha, adhesión y asignación al curso de su sede (US-30, US-31)
UPDATE public.usuarios_sedes SET es_lider_sede = true WHERE perfil_id IN ('9fc64a9c-583f-5ea3-b88c-abdcd2b255fa', '5cbb1abc-39b4-5792-b984-9ef3de315b2f', '1aac4ad1-394b-509a-9fba-411b193bcc7c');

-- Instancias de curso del período actual

-- Clases semanales: las anteriores a la sesión actual ya se realizaron

-- Alumnas, apoderados, autorizaciones e inscripciones (US-07..US-12)

-- Asistencia de las clases realizadas: presente en las primeras N, ausente en el resto

-- Asistencia de tutoras de las clases realizadas: casi siempre presentes (US-33)
SELECT c.id, ti.tutor_id,
  CASE WHEN abs(hashtext(ti.tutor_id::text || c.numero_sesion::text)) % 6 = 0 THEN 'ausente' ELSE 'presente' END::public.estado_asistencia,
  ti.tutor_id
FROM public.clases c
JOIN public.tutores_instancia ti ON ti.instancia_curso_id = c.instancia_curso_id
WHERE c.estado = 'realizada'
ON CONFLICT (clase_id, tutor_id) DO NOTHING;

